/** Reject URL spellings a URL parser or a downstream router could reinterpret. */
function parseEnvironmentUrl(rawValue: string): URL {
  if (!/^[a-z][a-z\d+.-]*:\/\/[^/?#]+/i.test(rawValue)
    || rawValue !== rawValue.trim() || /[\u0000-\u001f\u007f\\]/.test(rawValue)) {
    throw new Error("Invalid environment URL.");
  }
  const url = new URL(rawValue);
  if (!["http:", "https:", "ws:", "wss:"].includes(url.protocol) || url.username || url.password) {
    throw new Error("Environment URL must use HTTP(S) or WS(S) without user information.");
  }
  const rawPath = rawValue.replace(/^[a-z][a-z\d+.-]*:\/\/[^/?#]*/i, "").split(/[?#]/, 1)[0]!;
  validateEnvironmentPath(rawPath);
  return url;
}

function validateEnvironmentPath(path: string): void {
  if (/[\u0000-\u001f\u007f\\]/.test(path) || /%(?![\da-f]{2})/i.test(path)
    || /%(?:0[\da-f]|1[\da-f]|7f|5c)/i.test(path)) {
    throw new Error("Invalid environment path.");
  }
  for (const segment of path.split("/")) {
    const dots = segment.replace(/%2e/ig, ".");
    if (dots === "." || dots === "..") throw new Error("Environment path cannot traverse directories.");
  }
  if (path.replace(/\/+$/, "").includes("//")) throw new Error("Invalid empty environment path segment.");
}

/** Canonical environment directory, retaining encoded opaque path components. */
export function normalizeHttpBaseUrl(rawValue: string): string {
  const url = parseEnvironmentUrl(rawValue);
  if (url.protocol === "ws:") url.protocol = "http:";
  else if (url.protocol === "wss:") url.protocol = "https:";
  url.pathname = url.pathname.replace(/\/+$/, "") + "/";
  url.search = "";
  url.hash = "";
  return url.toString();
}

export function deriveWsBaseUrl(httpBaseUrl: string): string {
  const url = new URL(normalizeHttpBaseUrl(httpBaseUrl));
  url.protocol = url.protocol === "https:" ? "wss:" : "ws:";
  return url.toString();
}

/** A ws-only connection setting may already name the original /ws socket. */
export function httpBaseUrlFromWebSocket(wsBaseUrl: string): string {
  const url = parseEnvironmentUrl(wsBaseUrl);
  url.pathname = url.pathname.replace(/^\/ws\/$/, "/").replace(/\/ws$/, "/");
  return normalizeHttpBaseUrl(url.toString());
}

/** Resolve logical /api, /oauth and /ws paths inside one environment, exactly once. */
export function environmentEndpointUrl(httpBaseUrl: string, reference: string): string {
  const base = new URL(normalizeHttpBaseUrl(httpBaseUrl));
  if (reference !== reference.trim()) throw new Error("Invalid endpoint URL whitespace.");
  let url: URL;
  if (/^[a-z][a-z\d+.-]*:/i.test(reference)) {
    url = parseEnvironmentUrl(reference);
    if (url.pathname === base.pathname.slice(0, -1)) url.pathname = base.pathname;
    if (url.origin !== base.origin || !url.pathname.startsWith(base.pathname)) {
      throw new Error("Endpoint URL is outside its environment.");
    }
  } else {
    if (reference.startsWith("//")) throw new Error("Endpoint authority is not a logical path.");
    const path = reference.split(/[?#]/, 1)[0]!;
    validateEnvironmentPath(path);
    const rooted = path.startsWith("/") ? path : "/" + path;
    const parent = base.pathname.slice(0, base.pathname.slice(0, -1).lastIndexOf("/") + 1);
    if (base.pathname !== "/" && parent !== "/" && rooted.startsWith(parent)
      && rooted !== base.pathname.slice(0, -1) && !rooted.startsWith(base.pathname)) {
      throw new Error("Endpoint path names another environment.");
    }
    const suffix = reference.slice(path.length);
    const mounted = rooted === base.pathname.slice(0, -1) ? base.pathname
      : rooted.startsWith(base.pathname) ? rooted : base.pathname + rooted.slice(1);
    url = new URL(mounted + suffix, base);
  }
  const relative = url.pathname.slice(base.pathname.length);
  if (base.pathname !== "/" && relative.startsWith(base.pathname.slice(1))) {
    throw new Error("Endpoint path repeats its environment prefix.");
  }
  return url.toString();
}

/** Socket base or explicit socket path; credentials never leave the HTTP environment. */
export function environmentWebSocketUrl(httpBaseUrl: string, wsBaseUrl: string): string {
  const base = new URL(normalizeHttpBaseUrl(httpBaseUrl));
  const socket = parseEnvironmentUrl(wsBaseUrl);
  if (socket.protocol === "ws:") socket.protocol = "http:";
  else if (socket.protocol === "wss:") socket.protocol = "https:";
  if (socket.origin !== base.origin) throw new Error("Socket origin differs from its environment.");
  const isBase = socket.pathname.replace(/\/+$/, "") === base.pathname.slice(0, -1);
  const url = new URL(environmentEndpointUrl(base.href, isBase ? "/ws" : socket.href));
  url.search = socket.search;
  url.hash = "";
  url.protocol = url.protocol === "https:" ? "wss:" : "ws:";
  return url.toString();
}

/** Absolute minted HTTP resources support the existing local-media fallback. No auth is added. */
export function environmentResourceUrl(httpBaseUrl: string, reference: string): string {
  if (/^https?:\/\//i.test(reference)) {
    normalizeHttpBaseUrl(httpBaseUrl);
    const url = parseEnvironmentUrl(reference);
    return url.toString();
  }
  return environmentEndpointUrl(httpBaseUrl, reference);
}

